sys_script_include.script:
var AutoPopulateLocation = Class.create();
AutoPopulateLocation.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

getLocation: function() {
    var workspaceId = this.getParameter('sysparm_workspace');
    var gr = new GlideRecord('x_746154_workspa_0_workspace_options');
    gr.get(workspaceId);
    return this.newItem().setAttribute('answer', gr.getValue('location'));
},
    type: 'AutoPopulateLocation'
});
